def test_min_periods_shared_with_sub_rollings(self, ds):
    r = ds.rolling({"x": 3, "time": 2})
    for key in ("v", "w"):
        assert r.rollings[key].min_periods == r.min_periods == 6

    r = ds.rolling({"x": 3, "time": 2}, min_periods=1)
    for key in ("v", "w"):
        assert r.rollings[key].min_periods == 1
